INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (1, 'tecnico-em-transacoes-imobiliarias', 'Técnico em Transações Imobiliárias', 'Desenvolva competências para atuar no mercado imobiliário, da prospecção de clientes à conclusão da negociação.', 'O curso Técnico em Transações Imobiliárias prepara você para compreender o funcionamento do mercado imobiliário, a documentação dos imóveis, as etapas de uma negociação e as responsabilidades profissionais da área.

A formação combina fundamentos de legislação, análise documental, atendimento ao cliente e prática de negociação, com uma trilha organizada para quem deseja ampliar suas oportunidades no setor.

Todo o conteúdo desta versão é demonstrativo e será substituído pelo material pedagógico oficial da instituição.', '["Entender a estrutura do mercado imobiliário brasileiro.","Identificar documentos e certidões essenciais em uma transação.","Conduzir atendimentos e negociações com ética e clareza.","Organizar o processo de compra e venda com segurança.","Reconhecer as atribuições e os limites da atuação profissional."]', 'Pessoas interessadas em ingressar ou se atualizar no mercado imobiliário, profissionais de atendimento e quem deseja compreender melhor o processo de compra e venda de imóveis.', 'Ensino médio em andamento ou concluído. Requisitos formais de registro profissional devem ser confirmados diretamente com a instituição.', 1, 1, 'intermediario', 'online', 1200, 189000, 1, 1, 100, 1, 70, 'published', 1, 'course-tti.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (2, 'tecnico-em-administracao', 'Técnico em Administração', 'Organize rotinas, documentos e processos com uma base sólida de gestão para apoiar empresas de diferentes portes.', 'A formação técnica em Administração apresenta os fundamentos da gestão, as rotinas administrativas, a organização de documentos e a relação entre pessoas, processos e resultados.

As aulas foram organizadas para quem precisa compreender o dia a dia de uma empresa e desenvolver uma postura profissional organizada, ética e orientada a resultados.

Conteúdo demonstrativo sujeito à substituição pelo material oficial da BrasilTec Educação.', '["Compreender as funções clássicas da administração.","Organizar rotinas, arquivos e documentos corporativos.","Apoiar processos de pessoas e de atendimento.","Utilizar indicadores simples para acompanhar resultados.","Comunicar-se com clareza em ambiente profissional."]', 'Quem está iniciando na área administrativa, busca recolocação profissional ou deseja organizar melhor os processos do próprio negócio.', 'Ensino médio em andamento ou concluído. Conhecimentos básicos de informática ajudam no aproveitamento.', 1, 2, 'iniciante', 'online', 1200, 169000, 1, 1, 100, 0, 70, 'published', 1, 'course-admin.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (3, 'tecnico-em-seguranca-do-trabalho', 'Técnico em Segurança do Trabalho', 'Aprenda a identificar riscos, apoiar programas de prevenção e fortalecer a cultura de segurança nas organizações.', 'O curso apresenta os princípios da segurança e saúde no trabalho, o papel das normas regulamentadoras e as práticas de prevenção de acidentes.

A trilha aborda inspeções, identificação de riscos, documentação e mobilização de equipes, sempre com foco na proteção das pessoas e na melhoria contínua dos ambientes de trabalho.

Versão demonstrativa: os conteúdos oficiais e as exigências regulatórias devem ser confirmados com a instituição.', '["Reconhecer os principais riscos ocupacionais.","Compreender a lógica das normas regulamentadoras.","Apoiar inspeções e programas de prevenção.","Participar da construção de uma cultura de segurança.","Organizar registros e evidências de ações preventivas."]', 'Profissionais que atuam ou desejam atuar em segurança do trabalho, lideranças operacionais e equipes de prevenção.', 'Ensino médio em andamento ou concluído. Requisitos regulatórios e de registro devem ser verificados diretamente com a instituição.', 5, 3, 'intermediario', 'online', 1200, 199000, 1, 1, 100, 0, 70, 'published', 1, 'course-safety.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (4, 'tecnico-em-recursos-humanos', 'Técnico em Recursos Humanos', 'Atue nos processos de recrutamento, desenvolvimento e cuidado com as pessoas dentro das organizações.', 'A formação em Recursos Humanos conecta as rotinas de pessoal à experiência das pessoas na organização. Você verá recrutamento, integração, desenvolvimento, indicadores e comunicação.

O curso foi pensado para quem deseja iniciar na área ou organizar melhor os processos de gestão de pessoas no próprio negócio.

Os perfis e conteúdos apresentados são demonstrativos.', '["Compreender o ciclo de vida do colaborador.","Apoiar processos de recrutamento e seleção.","Planejar integração e desenvolvimento de equipes.","Organizar indicadores de pessoas.","Cuidar da comunicação e do clima organizacional."]', 'Pessoas em início de carreira em RH, lideranças e profissionais que apoiam a gestão de equipes.', 'Ensino médio em andamento ou concluído. Habilidades de comunicação e organização são diferenciais.', 1, 4, 'iniciante', 'online', 1200, 159000, 0, 1, 100, 0, 70, 'published', 1, 'course-rh.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (5, 'assistente-administrativo', 'Assistente Administrativo', 'Formação por competência para quem quer dominar as rotinas essenciais de um escritório moderno.', 'Uma trilha objetiva para desenvolver as competências mais solicitadas em vagas administrativas: organização, comunicação, documentos, planilhas e atendimento.

Com aulas curtas e atividades práticas, o curso ajuda você a construir uma rotina de trabalho mais eficiente e a se preparar para os desafios do dia a dia.

Curso demonstrativo criado para apresentar a experiência da plataforma.', '["Organizar demandas e prioridades com método.","Redigir e arquivar documentos profissionais.","Comunicar-se com clareza por diferentes canais.","Utilizar ferramentas digitais de produtividade.","Aplicar boas práticas de atendimento e follow-up."]', 'Pessoas que buscam a primeira oportunidade administrativa ou desejam atualizar rotinas e ferramentas.', 'Ensino fundamental completo. Acesso a um computador e internet para as aulas práticas.', 2, 2, 'iniciante', 'online', 160, 49000, 1, 1, 100, 0, 70, 'published', 1, 'course-finance.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (6, 'excelencia-no-atendimento-ao-cliente', 'Excelência no Atendimento ao Cliente', 'Construa experiências de atendimento que geram confiança, fidelização e resultados para o negócio.', 'Um curso gratuito e introdutório sobre o que realmente faz diferença no atendimento: escuta, clareza, empatia e consistência.

Você vai conhecer a jornada do cliente, formas de lidar com reclamações e práticas de comunicação que aproximam a empresa de quem ela atende.

Curso demonstrativo gratuito para explorar todos os recursos do ambiente virtual de aprendizagem.', '["Entender a jornada e as expectativas do cliente.","Praticar escuta ativa e comunicação empática.","Conduzir conversas difíceis com equilíbrio.","Registrar e acompanhar solicitações.","Contribuir para uma experiência consistente."]', 'Profissionais de atendimento, vendas, suporte e qualquer pessoa que se comunique com clientes.', 'Não há pré-requisitos. Basta ter acesso à internet.', 2, 5, 'iniciante', 'online', 40, 0, 1, 1, 100, 1, 70, 'published', 1, 'course-service.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (7, 'lideranca-e-gestao-de-equipes', 'Liderança e Gestão de Equipes', 'Pós-graduação EAD para líderes que precisam transformar times em resultados sustentáveis.', 'Uma formação para quem lidera pessoas e precisa equilibrar direção, desenvolvimento e resultados. O percurso aborda fundamentos da liderança, times de alta performance e gestão de mudanças.

As aulas propõem reflexões e ferramentas aplicáveis ao cotidiano, com espaço para registrar planos de ação e acompanhar a própria evolução.

Conteúdo demonstrativo. A oferta, a carga horária e as condições da pós-graduação devem ser confirmadas com a instituição.', '["Diferenciar gestão e liderança na prática.","Desenvolver confiança e autonomia no time.","Conduzir conversas de feedback com clareza.","Acompanhar desempenho com indicadores úteis.","Liderar mudanças com menos ruído e mais adesão."]', 'Lideranças em diferentes níveis, gestores de equipes e profissionais preparados para assumir posições de liderança.', 'Profissionais com experiência em equipes ou em posições de coordenação. Requisitos formais da pós-graduação sob consulta.', 3, 6, 'avancado', 'online', 480, 289000, 0, 1, 100, 0, 70, 'published', 1, 'course-leadership.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (8, 'logistica-e-supply-chain', 'Logística e Supply Chain', 'Compreenda o fluxo de produtos, informações e recursos que sustenta a operação das empresas.', 'O curso apresenta a cadeia de suprimentos, os processos de estoque e armazenagem e a distribuição de produtos. A proposta é formar uma visão integrada da operação.

As aulas combinam conceitos e situações práticas para apoiar decisões mais eficientes e sustentáveis.

Conteúdo demonstrativo sujeito à atualização pela equipe pedagógica.', '["Entender a lógica da cadeia de suprimentos.","Organizar estoques e movimentações.","Acompanhar indicadores operacionais.","Reconhecer riscos e pontos de melhoria.","Integrar compras, armazenagem e distribuição."]', 'Profissionais de operações, logística, compras e atendimento que desejam ampliar a visão de processo.', 'Ensino médio em andamento ou concluído. Conhecimentos básicos de planilhas são recomendados.', 1, 7, 'intermediario', 'online', 1200, 179000, 0, 1, 100, 0, 70, 'published', 1, 'course-logistics.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');
INSERT INTO "courses" ("id", "slug", "title", "subtitle", "description", "objectives", "audience", "requirements", "category_id", "instructor_id", "level", "modality", "duration_hours", "price_cents", "is_featured", "certificate_enabled", "completion_percent", "require_assessment", "pass_score", "status", "demo", "cover_image", "created_by", "created_at", "updated_at") VALUES (9, 'informatica-e-transformacao-digital', 'Informática e Transformação Digital', 'Ganhe produtividade com ferramentas digitais, dados e uma postura segura no ambiente online.', 'Uma formação prática para usar a tecnologia a favor da sua rotina. Você vai explorar ferramentas de produtividade, organização de arquivos, colaboração e segurança digital.

O curso parte do essencial e avança para conceitos de dados e transformação digital, sempre com exemplos aplicáveis.

Curso demonstrativo para validação da experiência de aprendizagem.', '["Organizar arquivos e informações com eficiência.","Usar ferramentas de colaboração e produtividade.","Aplicar cuidados básicos de segurança digital.","Compreender o papel dos dados nas decisões.","Identificar oportunidades de melhoria digital."]', 'Pessoas que desejam desenvolver confiança no uso da tecnologia e melhorar a produtividade no trabalho.', 'Acesso a computador e internet. Não é necessário conhecimento técnico prévio.', 4, 8, 'iniciante', 'online', 120, 39000, 0, 1, 100, 0, 70, 'published', 1, 'course-tech.jpg', 1, '2026-06-26T10:00:00.000Z', '2026-10-24T00:45:13.714Z');

