INSERT INTO "assessments" ("id", "course_id", "title", "description", "pass_score", "max_attempts", "is_published", "created_at") VALUES (1, 1, 'Avaliação final — Transações Imobiliárias', 'Avaliação demonstrativa com questões de múltipla escolha sobre os principais conceitos do curso.', 70, 3, 1, '2026-07-06T10:00:00.000Z');
INSERT INTO "assessments" ("id", "course_id", "title", "description", "pass_score", "max_attempts", "is_published", "created_at") VALUES (2, 6, 'Avaliação final — Atendimento ao Cliente', 'Verifique o que você aprendeu sobre escuta, comunicação e condução de reclamações.', 70, 3, 1, '2026-07-06T10:00:00.000Z');

INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (1, 1, 'Qual documento é a principal evidência da propriedade de um imóvel urbano?', 'multiple', '["Contrato de locação","Matrícula do imóvel","Comprovante de IPTU","Anúncio de venda"]', 1, 'A matrícula, registrada no cartório de registro de imóveis, identifica a propriedade e os ônus que recaem sobre o imóvel.', 0);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (2, 1, 'O que significa due diligence em uma transação imobiliária?', 'multiple', '["Divulgar o imóvel nas redes sociais","Negociar o valor sem análise documental","Verificar documentos, riscos e pendências antes da compra","Assinar o contrato imediatamente"]', 2, 'A due diligence reúne a análise documental e jurídica necessária para reduzir riscos antes da conclusão da negociação.', 1);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (3, 1, 'Uma escuta ativa no atendimento ao cliente envolve:', 'multiple', '["Interromper para apresentar logo uma solução","Prestar atenção, confirmar o entendimento e registrar o pedido","Encaminhar o cliente sem contexto","Evitar perguntas para agilizar a conversa"]', 1, 'Escutar de forma ativa significa compreender a necessidade, validar o entendimento e registrar informações relevantes.', 2);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (4, 1, 'Qual comportamento fortalece a ética profissional na intermediação imobiliária?', 'multiple', '["Prometer resultados garantidos para fechar o negócio","Omitir pendências para proteger o vendedor","Informar com transparência os limites da atuação","Compartilhar dados do cliente sem autorização"]', 2, 'Transparência sobre atribuições, riscos e limites é essencial para uma relação profissional confiável.', 3);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (5, 1, 'Antes de divulgar um imóvel, é recomendável:', 'multiple', '["Confirmar dados, valor, condições e autorização do proprietário","Publicar apenas com uma foto","Definir o preço sem ouvir o proprietário","Ignorar a documentação"]', 0, 'A divulgação responsável depende de informações conferidas e autorização de quem representa o imóvel.', 4);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (6, 2, 'Empatia no atendimento significa:', 'multiple', '["Concordar com tudo que o cliente diz","Buscar compreender a perspectiva e o impacto da situação","Resolver apenas o que está no script","Transferir o atendimento rapidamente"]', 1, 'Empatia é compreender a experiência do outro sem necessariamente concordar com todas as suas conclusões.', 0);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (7, 2, 'Diante de uma reclamação, a primeira ação recomendada é:', 'multiple', '["Justificar imediatamente o erro da empresa","Pedir que o cliente envie tudo novamente","Ouvir com atenção, confirmar os fatos e registrar o caso","Encerrar a conversa"]', 2, 'Ouvir e confirmar os fatos evita respostas precipitadas e permite encaminhar a solução correta.', 1);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (8, 2, 'Um follow-up eficaz deve:', 'multiple', '["Ser feito apenas quando o cliente cobrar","Informar prazo, responsável e próximo passo combinado","Ser enviado sem contexto","Depender de memória, sem registro"]', 1, 'Combinar prazo, responsável e próximo passo torna o acompanhamento previsível e confiável.', 2);
INSERT INTO "questions" ("id", "assessment_id", "text", "type", "options", "correct_index", "explanation", "position") VALUES (9, 2, 'Qual prática contribui para uma experiência consistente?', 'multiple', '["Registrar as informações relevantes do atendimento","Usar respostas diferentes para cada canal","Evitar confirmar o entendimento","Prometer prazos sem checar a operação"]', 0, 'Registros permitem continuidade, análise de recorrências e melhoria do atendimento.', 3);

