INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (1, 'Como funciona o acesso aos cursos?', 'Após criar sua conta e concluir a matrícula, os cursos liberados aparecem em “Meus cursos”, na área do aluno. As aulas podem ser assistidas pelo navegador, no computador ou no celular.', 0, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (2, 'Os cursos são 100% online?', 'As trilhas demonstrativas desta plataforma são 100% online. A modalidade, a carga horária e eventuais encontros ao vivo de cada curso oficial devem ser confirmados com a BrasilTec Educação.', 1, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (3, 'Qual é a duração dos cursos?', 'A carga horária aparece na página de cada curso. O ritmo de conclusão depende da sua disponibilidade e dos critérios definidos para a formação.', 2, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (4, 'Como faço minha matrícula?', 'Escolha um curso, clique em “Quero me matricular” e siga o fluxo. Cursos gratuitos liberam o acesso imediatamente. Cursos pagos dependem da confirmação do pagamento ou de aprovação administrativa.', 3, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (5, 'Quais são as formas de pagamento?', 'A plataforma está preparada para pagamentos online via Mercado Pago. Enquanto o gateway não estiver configurado, o pedido fica pendente e a equipe pode orientar o atendimento. Nunca solicitamos dados completos de cartão por aqui.', 4, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (6, 'Como funciona o certificado?', 'A emissão depende dos critérios de conclusão do curso: aulas concluídas, percentual mínimo e, quando houver, aprovação na avaliação. O certificado traz um código público de verificação.', 5, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (7, 'O certificado é reconhecido?', 'A disponibilidade e eventuais reconhecimentos variam conforme o curso e a regulamentação aplicável. Consulte a BrasilTec Educação nos canais oficiais antes de se matricular. A plataforma não substitui essa confirmação.', 6, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (8, 'Terei suporte durante o curso?', 'Você pode enviar dúvidas pelo formulário de contato e acompanhar seus pedidos na área do aluno. Os canais oficiais de atendimento estão disponíveis no rodapé.', 7, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (9, 'Como funcionam as avaliações?', 'Quando o curso possui avaliação, você verá o número de tentativas permitidas e a nota mínima. O resultado e o feedback de cada questão ficam disponíveis no histórico.', 8, 1);
INSERT INTO "faqs" ("id", "question", "answer", "position", "published") VALUES (10, 'Posso estudar pelo celular?', 'Sim. O site, o player e o painel do aluno foram construídos para funcionar em computadores, tablets e celulares, respeitando boas práticas de acessibilidade.', 9, 1);

